<!-- Client-side Interactive Logic for Live Message Simulation -->
<script>
    function appendQuickText(text) {
      const input = document.getElementById('academic-chat-input');
      if (input) {
        input.value = text;
        input.focus();
      }
    }

    document.addEventListener('DOMContentLoaded', () => {
      const input = document.getElementById('academic-chat-input');
      const sendBtn = document.getElementById('send-message-btn');
      const container = document.getElementById('chat-messages-container');

      function sendMessage() {
        if (!input || !input.value.trim() || !container) return;
        const msg = input.value.trim();
        const time = new Date().toLocaleTimeString('id-ID', { hour: '2-digit', minute: '2-digit' }) + ' WIB';

        const bubbleHTML = document.createElement('div');
        bubbleHTML.className = 'flex flex-col gap-1 items-end max-w-2xl ml-auto animate-fade-in';
        bubbleHTML.innerHTML = `
          <div class="flex items-center gap-2 pr-1">
            <span class="font-label-md text-label-md text-primary font-bold">Anda ({{ auth()->user()->nama_lengkap }})</span>
          </div>
          <div class="p-4 rounded-2xl rounded-tr-sm bg-primary-container text-on-primary shadow-md space-y-2">
            <p class="font-body-md text-body-md leading-relaxed text-surface-bright">` +
            msg.replace(/</g, "&lt;").replace(/>/g, "&gt;") +
            `</p>
            <div class="flex items-center justify-end gap-1.5 pt-1 text-on-primary-container">
              <span class="font-label-sm text-label-sm">` + time + `</span>
              <span class="material-symbols-outlined text-[16px] text-secondary-container">done_all</span>
            </div>
          </div>
        `;
        
        container.appendChild(bubbleHTML);
        input.value = '';
        container.scrollTop = container.scrollHeight;
      }

      if (sendBtn) {
        sendBtn.addEventListener('click', sendMessage);
      }

      if (input) {
        input.addEventListener('keydown', (e) => {
          if (e.key === 'Enter') {
            e.preventDefault();
            sendMessage();
          }
        });
      }

      // Scroll to bottom on initial render
      if (container) {
        container.scrollTop = container.scrollHeight;
      }
    });
  </script>
